CONTRACTS = json.loads('{"supabase/migrations/202609100001_schema.sql": "720a0a4793c281b69950c659c541d8536032fd19a03d350d0979902e67434fc7", "supabase/migrations/202609100002_permissions.sql": "45a1e78c4f02668900482fb70736ccc128fce3e04e7c0621afaa6f07bdfa019c", "supabase/migrations/202609100003_rls.sql": "3f35cf2a9900460d120060db2a87a99666d5318236ba31f19be110f90500e3b0", "supabase/migrations/202609100004_rpc.sql": "5bce70004036ded506d0ef2e7aa8c5d277ee51cc1aeda523a8a6a838ea01f2c9", "supabase/migrations/202609100005_realtime_audit.sql": "e8d45c0e2bc408b563903447d7bf12aeac838ef1f87fc53f82645d43c7c013e0", "supabase/migrations/202609100006_role_catalog.sql": "aacdde0e2f5600b9c0c62e83353a26b1e497ea770e801dd85043796635d58d7e"}')

def digest(data):
    return hashlib.sha256(data.replace(b'\r\n', b'\n')).hexdigest()

def safe_target(root, relative):
    name = Path(relative)
    if name.is_absolute() or '..' in name.parts:
        raise ValueError('Invalid update path')
    target = root / name
    if target.is_symlink() or not target.resolve().is_relative_to(root):
        raise ValueError('Unsafe project path: ' + relative)
    for parent in target.parents:
        if parent == root:
            break
        if parent.is_symlink():
            raise ValueError('Symbolic link in project path: ' + relative)
    return target

def atomic_write(target, data, mode):
    target.parent.mkdir(parents=True, exist_ok=True)
    temp = None
    try:
        with tempfile.NamedTemporaryFile(dir=target.parent, prefix='.moy-admin-', delete=False) as handle:
            temp = Path(handle.name)
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp, mode)
        os.replace(temp, target)
    finally:
        if temp is not None and temp.exists():
            temp.unlink()

def main():
    root = Path.cwd().resolve()
    if not (root / 'pubspec.yaml').is_file() or not (root / 'lib').is_dir():
        print('Откройте терминал VS Code в папке moy_prihod, рядом с pubspec.yaml.')
        return 1
    conflicts = []
    pending = []
    preserved = []
    for relative, checksum in CONTRACTS.items():
        target = safe_target(root, relative)
        if not target.is_file() or digest(target.read_bytes()) != checksum:
            conflicts.append(relative)
    for relative, item in CHANGES.items():
        target = safe_target(root, relative)
        replacement = base64.b64decode(item['data'], validate=True)
        if digest(replacement) != item['after']:
            raise ValueError('Повреждено содержимое обновления: ' + relative)
        if target.exists() and not target.is_file():
            conflicts.append(relative)
            continue
        previous = target.read_bytes() if target.exists() else None
        checksum = digest(previous) if previous is not None else None
        if checksum == item['after']:
            continue
        if checksum != item['before']:
            # This report records local verification history, not an app or
            # schema contract. Keep its bytes while updating the application.
            if relative == 'docs/VERIFICATION.md' and previous is not None:
                preserved.append(relative)
                continue
            conflicts.append(relative)
            continue
        mode = stat.S_IMODE(target.stat().st_mode) if target.exists() else 0o644
        pending.append((relative, target, previous, replacement, mode))
    if conflicts:
        print('Обновление не установлено. Эти файлы отличаются от ожидаемой версии:')
        print('\n'.join(sorted(set(conflicts))))
        print('Ничего не изменено. Пришлите этот вывод для совместимого обновления.')
        return 1
    for relative in preserved:
        print('Ваш документ сохранён без изменений:', relative)
    if not pending:
        print('Обновление уже установлено. Выполните flutter analyze и flutter test.')
        return 0
    backup = root.parent / 'moy_prihod_update_backups' / datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup.mkdir(parents=True, exist_ok=False)
    for relative, target, previous, replacement, mode in pending:
        if previous is not None:
            saved = backup / relative
            saved.parent.mkdir(parents=True, exist_ok=True)
            saved.write_bytes(previous)
            os.chmod(saved, mode)
    manifest = {'project': str(root), 'new_files': [rel for rel, _, data, _, _ in pending if data is None],
                'files': [rel for rel, _, _, _, _ in pending], 'preserved_files': preserved}
    (backup / 'manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    written = []
    try:
        for relative, target, previous, replacement, mode in pending:
            actual = target.read_bytes() if target.exists() else None
            if actual != previous:
                raise RuntimeError('Файл изменился во время обновления: ' + relative)
            written.append((target, previous, mode))
            atomic_write(target, replacement, mode)
    except BaseException:
        for target, previous, mode in reversed(written):
            if previous is None:
                if target.exists():
                    target.unlink()
            else:
                atomic_write(target, previous, mode)
        print('Запись прервана; прежние файлы восстановлены. Резервная копия:', backup)
        raise
    print('Обновление установлено. Изменено файлов:', len(pending))
    print('Резервная копия:', backup)
    print('В том же терминале: flutter analyze, затем flutter test.')
    print('После успешных проверок: npx supabase db push (только миграция 202609100007_administration.sql).')
    print('Инструкция: docs/ADMIN_UPDATE.md')
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main())
    except Exception as error:
        print('Обновление остановлено:', error)
        sys.exit(1)
